const j = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
return [{ json: {
  branch: j.branch || 'voice_session',
  chat_id: j.chat_id,
  text: String(j.text || '').trim(),
  voice_file_id: j.voice_file_id || null,
} }];

const ctx = $('Code - Normalize Input').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.session_id && r.status !== 'closed');
rows.sort((a, b) => String(b.updated_at || b.created_at || '').localeCompare(String(a.updated_at || a.created_at || '')));
let session = rows[0] || null;
if (session) {
  const age = Date.now() - new Date(session.updated_at).getTime();
  if (age > 24 * 3600 * 1000) session = null;
}
let route;
if (ctx.branch === 'voice_start') route = 'start';
else if (ctx.branch === 'voice_cancel') route = session ? 'cancel' : 'no_session';
else if (!session) route = 'no_session';
else route = ctx.voice_file_id ? 'voice' : 'text';
return [{ json: { ...ctx, session, route } }];

const ctx = $('Code - Merge Context').first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hotels = $input.all().map(i => i.json).filter(h => h && h.hotel_id)
  .sort((a, b) => String(a.name).localeCompare(String(b.name), 'uk'));
let reply;
if (!hotels.length) {
  reply = 'У базі ще нема готелів 🙈 Скажи Владу.';
} else {
  reply = '🏨 Про який готель розповідаєш? Напиши номер зі списку (або назву):\n\n' +
    hotels.map((h, i) => `${i + 1}. <code>${esc(h.name)}</code>`).join('\n') +
    '';
}
return [{ json: {
  chat_id: ctx.chat_id,
  hotel_options_pg: '{' + hotels.map(h => h.hotel_id).join(',') + '}',
  reply_text: reply,
} }];

const ctx = $('Code - Merge Context').first().json;
const inc = $input.first().json;
let text = ctx.text;
if (ctx.voice_file_id) text = String(inc.text || '').trim();
const kind = ctx.voice_file_id ? 'voice' : 'text';
const state = !text ? 'empty' : ctx.session.status;
return [{ json: { ...ctx, text, kind, state } }];

const ctx = $('Code - Resolve Text').first().json;
const f = $input.first().json;
const opts = Array.isArray(ctx.session.hotel_options) ? ctx.session.hotel_options : [];
let hotel_id = null;
if (f && f.hotel_id) {
  hotel_id = f.hotel_id;
} else {
  const n = parseInt(String(ctx.text).replace(/\D/g, ''), 10);
  if (Number.isInteger(n) && n >= 1 && n <= opts.length) hotel_id = opts[n - 1];
}
const ok = !!hotel_id;
return [{ json: {
  ok,
  chat_id: ctx.chat_id,
  session_id: ctx.session.session_id,
  hotel_id,
  reply_text: ok ? '' : `Не розпізнав 🙈 Тапни на назву готелю зі списку або напиши номер від 1 до ${opts.length} (або «❌ Скасувати»).`,
} }];

const ctx = $('Code - Resolve Text').first().json;
const t = String(ctx.text).toLowerCase().replace(/[.!\s]+$/g, '').trim();
const is_done = ['все', 'усе', 'всё', 'це все', 'це усе', 'я все', 'done'].includes(t);
return [{ json: { ...ctx, is_done } }];

const hotel = $('Supabase - Get Session Hotel').first().json;
const msgs = $input.all().map(i => i.json).filter(m => m && m.content);
const transcript = msgs.map((m, i) => (i + 1) + ') ' + m.content).join('\n');
const shape = { differentiator: 'чим готель відрізняється, головна фішка (рядок або null)', best_for: 'кому підходить (рядок або null)', not_for: 'кому не підходить (рядок або null)', honest_con: 'мінус, який Іра озвучила б клієнту (рядок або null)', visited_personally: 'true, false або null', personal_impression: 'що Іра відчуває, особисте враження (рядок або null)', extra_notes: 'інші корисні факти зі слів Іри (рядок або null)' };
const system = 'Ти асистент luxury travel-агентства. Іра, турагент, диктує враження про готель. Витягни з її слів структуровані поля. СУВОРІ ПРАВИЛА: використовуй ТІЛЬКИ те, що Іра сказала; нічого не вигадуй і не додавай від себе; якщо поля немає в її словах — став null; пиши стисло її словами, українською. Повідомлення, що починаються з "Правка:", — уточнення й мають пріоритет над попередніми. Поверни СТРОГО валідний JSON без пояснень у форматі: ' + JSON.stringify(shape);
const body = { model: 'gpt-4.1', temperature: 0.2, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: system }, { role: 'user', content: 'Готель: ' + (hotel.name || '') + '\n\nПовідомлення Іри по порядку:\n' + transcript } ] };
return [{ json: { openai_body: body, hotel_name: hotel.name || '' } }];

const ctx = $('Code - Resolve Text').first().json;
const prep = $('Code - Build Structuring Prompt').first().json;
const res = $input.first().json;
let ins = null;
try { ins = JSON.parse(res.choices[0].message.content); } catch (e) { ins = null; }
if (!ins || typeof ins !== 'object') {
  return [{ json: { chat_id: ctx.chat_id, session_id: ctx.session.session_id, next: 'error', reply_text: 'Не вдалося обробити відповідь 🙈 Натисни «✅ Це все» ще раз.' } }];
}
const clean = v => (v === null || v === undefined) ? null : (String(v).trim() || null);
const d = {
  differentiator: clean(ins.differentiator),
  best_for: clean(ins.best_for),
  not_for: clean(ins.not_for),
  honest_con: clean(ins.honest_con),
  visited_personally: (String(ins.visited_personally).toLowerCase() === 'true') ? true : (String(ins.visited_personally).toLowerCase() === 'false') ? false : null,
  personal_impression: clean(ins.personal_impression),
  extra_notes: clean(ins.extra_notes),
};
const questions = { differentiator: 'чим цей готель відрізняється від інших', best_for: 'кому він підходить', not_for: 'кому він НЕ підходить', honest_con: 'який мінус ти б озвучила клієнту', visited_personally: 'чи була ти там особисто' };
const missing = Object.keys(questions).filter(k => d[k] === null);
const next = (missing.length && !ctx.session.gap_round_done && ctx.session.status === 'collecting') ? 'gaps' : 'confirm';
const yn = v => v === true ? 'так' : v === false ? 'ні' : '—';
const line = (l, v) => l + ': ' + (v || '—');
const card = 'Ось що я зрозумів про «' + prep.hotel_name + '»:\n\n' + [line('Чим відрізняється', d.differentiator), line('Кому підходить', d.best_for), line('Кому не підходить', d.not_for), line('Мінус', d.honest_con), 'Була особисто: ' + yn(d.visited_personally), line('Враження', d.personal_impression), line('Додатково', d.extra_notes)].join('\n') + '\n\nЯкщо все вірно — натисни «👍 Зберегти». Якщо щось не так — надішли правку (голосовим або текстом).';
const gaps = 'Майже все є 👍 Щоб пости були точнішими, розкажи ще коротко:\n' + missing.map(k => '• ' + questions[k]).join('\n') + '\n\nМожна голосовим. Якщо додати нічого — натисни «✅ Це все».';
return [{ json: { chat_id: ctx.chat_id, session_id: ctx.session.session_id, next, draft_json: JSON.stringify(d), reply_text: next === 'gaps' ? gaps : card } }];

const ctx = $('Code - Resolve Text').first().json;
const t = String(ctx.text).toLowerCase().replace(/[.!\s]+$/g, '').trim();
const approved = ['ок', 'окей', 'ok', 'okay', 'так', 'все', 'усе', 'вірно', 'підтверджую', '👍', '✅'].includes(t);
return [{ json: { ...ctx, approved } }];

const ctx = $('Code - Detect Approval').first().json;
const last = $input.first().json;
const n = last && last.insight_id ? parseInt(String(last.insight_id).replace(/\D/g, ''), 10) : 0;
const insight_id = 'INS-' + String((n || 0) + 1).padStart(3, '0');
let d = ctx.session.draft;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = null; } }
d = d || {};
const msgs = $('Supabase - Get Messages For Save').all().map(i => i.json).filter(m => m && m.content);
const v = d.visited_personally;
return [{ json: {
  insight_id,
  hotel_id: ctx.session.hotel_id,
  session_id: ctx.session.session_id,
  chat_id: ctx.chat_id,
  differentiator: d.differentiator ?? null,
  best_for: d.best_for ?? null,
  not_for: d.not_for ?? null,
  honest_con: d.honest_con ?? null,
  visited_personally: v === true ? 'true' : v === false ? 'false' : null,
  personal_impression: d.personal_impression ?? null,
  extra_notes: d.extra_notes ?? null,
  raw_transcript: msgs.map(m => m.content).join('\n---\n'),
} }];

// Досьє тільки зростає: нове дописується до старого, старе не перезаписується.
const ins = $('Code - Build Insight Row').first().json;
const h = $input.first().json || {};
const norm = s => String(s == null ? '' : s).toLowerCase().replace(/\s+/g, ' ').trim();
const clean = s => (s == null ? '' : String(s)).trim();
// Поля-переліки: ділимо по ';', дописуємо лише те, чого ще нема в старому тексті.
const mergeList = (oldV, newV) => {
  const o = clean(oldV), n = clean(newV);
  if (!n) return o || null;
  if (!o) return n;
  const on = norm(o), nn = norm(n);
  if (on.includes(nn)) return o;
  const add = n.split(/;\s*/).map(clean).filter(s => s && !on.includes(norm(s)));
  return add.length ? o + '; ' + add.join('; ') : o;
};
// Нотатки: цілий блок дописуємо, якщо його ще нема.
const mergeNotes = (oldV, newV) => {
  const o = clean(oldV), n = clean(newV);
  if (!n) return o || null;
  if (!o) return n;
  if (norm(o).includes(norm(n))) return o;
  if (norm(n).includes(norm(o))) return n;
  return o + '\n' + n;
};
// «Була особисто» тільки вмикається: раз true — лишається true.
const visited = h.ira_visited === true || ins.visited_personally === 'true';
const notes = [ins.personal_impression, ins.extra_notes].filter(Boolean).join('. ');
return [{ json: {
  hotel_id: ins.hotel_id,
  key_detail: mergeList(h.key_detail, ins.differentiator),
  who_for: mergeList(h.who_for, ins.best_for),
  who_not_for: mergeList(h.who_not_for, ins.not_for),
  caveat: mergeList(h.caveat, ins.honest_con),
  ira_visited: visited ? 'true' : 'false',
  ira_notes: visited ? mergeNotes(h.ira_notes, notes) : (h.ira_notes ?? null),
} }];

const ctx = $('Code - Readiness Ctx').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const h = $('Supabase - Get Hotel (Readiness)').all().map(i => i.json).find(x => x && x.hotel_id === ctx.hotel_id);
if (!h || h.status !== 'needs_review') return [{ json: { act: 'none' } }];
const photos = $('Supabase - Get Photos (Readiness)').all().map(i => i.json).filter(x => x && x.media_id).length;
const cards = $('Supabase - Get Insights (Readiness)').all().map(i => i.json).filter(x => x && x.insight_id && x.status === 'confirmed').length;
const needPhotos = Math.max(0, 5 - photos);
const needCard = cards === 0;
const name = '<b>' + esc(h.name) + '</b>';
if (!needPhotos && !needCard) return [{ json: { act: 'promote', hotel_id: h.hotel_id, chat_id: ctx.chat_id,
  text: 'Готово ✅ ' + name + ' додано в роботу. Агент почне писати про нього з плану на наступний тиждень (неділя 19:00).' } }];
const lines = [];
if (needPhotos) lines.push('📸 ще ' + needPhotos + ' фото (зараз ' + photos + ' із 5) — закинь у папку й натисни «✅ Фото готово»');
if (needCard) lines.push('🏨 розкажи про готель голосом — кнопка нижче');
return [{ json: { act: 'missing', need_card: needCard, hotel_id: h.hotel_id, chat_id: ctx.chat_id,
  text: name + ' ще не в роботі. Щоб агент почав про нього писати, бракує:\n\n' + lines.join('\n') } }];
